---@class GameDeviceActive
---@field idfa        @ 设备IDFA
---@field caid        @ 设备CAID
---@field imei        @ 设备IMEI
---@field gmac        @ 设备MAC
---@field gmsn        @ 设备SN
---@field gmip        @ ip地址
---@field gcid        @ 渠道ID

---@return GameDeviceActive
function QuickTaData:GameDeviceActive(_dety, _idfa, _caid, _imei, _gmac, _gmsn, _gmip, _gcid)
    return {
        dety = _dety, ---  设备类型    string        y        2019-06-20    kk@    设备类型[ios、android、iosyy]
        idfa = _idfa, ---  设备IDFA    string        y        2019-06-20    kk@    设备IDFA
        caid = _caid, ---  设备CAID    string        y        2021-01-21    kk@    设备CAID
        imei = _imei, ---  设备IMEI    string        y        2019-06-20    kk@    设备IMEI
        gmac = _gmac, ---  设备MAC      string        y        2019-06-20    kk@    玩家手持设备为IOS的，获取此数据
        gmsn = _gmsn, ---  设备SN    string        y        2019-06-20    kk@    手持设备的产品序列号，必须获取
        gmip = _gmip, ---  ip地址    string        y        2019-06-20    kk@    即上网ip地址，这里指上网的公网ip地址
        gcid = _gcid, ---  渠道ID      string        y        2019-06-20    kk@    渠道ID
    }
end

