--{{{ 数数部分
---@class TrackPropertyType
TrackPropertyType = {
    UserSet = 0, -- 设置用户属性. 该接口上传的属性将会覆盖原有的属性值..
    UserAdd = 1, -- 对数值类用户属性进行累加. 如果该属性还未被设置，则会赋值 0 后再进行计算.
    UserAppend = 2, -- 对 List 类型的用户属性进行追加
    UserDelete = 3, -- 删除用户数据. 之后再查询该名用户的用户属性，但该用户产生的事件仍然可以被查询到.
    UserSetOnce = 4, -- 设置用户属性. 当该属性之前已经有值的时候，将会忽略这条信息.
    UserUniqAppend = 5, -- 对 List 类型的用户属性进行去重追加.
    UserUnset = 6             -- 重置一个用户属性.  该类型只用到了Keys  values 设置0
}

---@class TrackEventType
TrackEventType = {
    Default = -1,
    First = 0,
    Updatable = 1,
    OverWritable = 2
}
--}}}
